import { useRef, useEffect } from "react";
import { TerminalSquare, Globe, FileText, Smartphone, Settings, Sparkles } from "lucide-react";
import { newBrowserTabUrl } from "../lib/browserSettings";
import { formatBindingLabel, isMacShortcutPlatform, shortcutLabel } from "../lib/shortcuts";

export type PopoverAgent = {
  name: string;
  command: string;
  args: string;
};

interface NewTabPopoverProps {
  open: boolean;
  onClose: () => void;
  onNewTerminal: () => void;
  onNewBrowser: (url?: string) => void;
  onNewMarkdown?: () => void;
  onNewMobileEmulator?: () => void;
  onOpenSettings?: () => void;
  agents?: PopoverAgent[];
  onLaunchAgent?: (agent: PopoverAgent) => void;
}

export function NewTabPopover({
  open,
  onClose,
  onNewTerminal,
  onNewBrowser,
  onNewMarkdown,
  onNewMobileEmulator,
  onOpenSettings,
  agents,
  onLaunchAgent,
}: NewTabPopoverProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const isMac = isMacShortcutPlatform();

  useEffect(() => {
    if (!open) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.preventDefault();
        e.stopPropagation();
        onClose();
      }
    };

    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        onClose();
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    document.addEventListener("mousedown", handleClickOutside);

    return () => {
      window.removeEventListener("keydown", handleKeyDown);
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [open, onClose]);

  if (!open) return null;

  return (
    <div
      ref={containerRef}
      role="dialog"
      aria-label="New tab menu"
      className="absolute top-full left-0 mt-1 w-80 rounded-xl border border-border bg-popover text-popover-foreground shadow-2xl z-50 p-2 text-xs select-none backdrop-blur-md"
    >
      <div className="flex flex-col gap-0.5">
        <button
          type="button"
          onClick={() => {
            onNewTerminal();
            onClose();
          }}
          className="flex items-center justify-between px-2.5 py-1.5 rounded-lg text-left text-foreground hover:bg-accent/50 transition-colors group"
        >
          <div className="flex items-center gap-2.5">
            <TerminalSquare className="size-4 text-muted-foreground group-hover:text-foreground" />
            <span className="font-medium">New Terminal</span>
          </div>
          <span className="text-[11px] font-mono text-muted-foreground">
            {shortcutLabel("tab.newTerminal", isMac)}
          </span>
        </button>

        <button
          type="button"
          onClick={() => {
            onNewBrowser(newBrowserTabUrl());
            onClose();
          }}
          className="flex items-center justify-between px-2.5 py-1.5 rounded-lg text-left text-foreground hover:bg-accent/50 transition-colors group"
        >
          <div className="flex items-center gap-2.5">
            <Globe className="size-4 text-muted-foreground group-hover:text-foreground" />
            <span className="font-medium">New Browser Tab</span>
          </div>
          <span className="text-[11px] font-mono text-muted-foreground">
            {shortcutLabel("tab.newBrowser", isMac)}
          </span>
        </button>

        {onNewMarkdown ? (
          <button
            type="button"
            onClick={() => {
              onNewMarkdown();
              onClose();
            }}
            className="flex items-center justify-between px-2.5 py-1.5 rounded-lg text-left text-foreground hover:bg-accent/50 transition-colors group"
          >
            <div className="flex items-center gap-2.5">
              <FileText className="size-4 text-muted-foreground group-hover:text-foreground" />
              <span className="font-medium">New Markdown</span>
            </div>
            <span className="text-[11px] font-mono text-muted-foreground">
              {formatBindingLabel({ key: "m", mod: true, shift: true }, isMac)}
            </span>
          </button>
        ) : null}

        {onNewMobileEmulator ? (
          <button
            type="button"
            onClick={() => {
              onNewMobileEmulator();
              onClose();
            }}
            className="flex items-center justify-between px-2.5 py-1.5 rounded-lg text-left text-foreground hover:bg-accent/50 transition-colors group"
          >
            <div className="flex items-center gap-2.5">
              <Smartphone className="size-4 text-muted-foreground group-hover:text-foreground" />
              <span className="font-medium">New Mobile Emulator</span>
            </div>
            <span className="text-[11px] font-mono text-muted-foreground">
              {formatBindingLabel({ key: "e", mod: true, alt: true, shift: true }, isMac)}
            </span>
          </button>
        ) : null}

        {agents && agents.length > 0 ? (
          <div className="flex flex-col gap-0.5 border-t border-border/60 pt-1.5 mt-0.5">
            <div className="px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground/60">
              AGENTS
            </div>
            {agents.map((agent) => {
              const label = agent.name.charAt(0).toUpperCase() + agent.name.slice(1);
              return (
                <button
                  key={agent.name}
                  type="button"
                  onClick={() => {
                    onLaunchAgent?.(agent);
                    onClose();
                  }}
                  className="flex items-center justify-between px-2.5 py-1.5 rounded-lg text-left text-foreground hover:bg-accent/50 transition-colors group"
                >
                  <div className="flex items-center gap-2.5">
                    <Sparkles className="size-4 text-muted-foreground group-hover:text-foreground" />
                    <span className="font-medium">{label}</span>
                  </div>
                </button>
              );
            })}
          </div>
        ) : null}

        {onOpenSettings ? (
          <button
            type="button"
            onClick={() => {
              onOpenSettings();
              onClose();
            }}
            className="flex items-center justify-between px-2.5 py-1.5 rounded-lg text-left text-foreground hover:bg-accent/50 transition-colors group border-t border-border/60 mt-0.5 pt-1.5"
          >
            <div className="flex items-center gap-2.5">
              <Settings className="size-4 text-muted-foreground group-hover:text-foreground" />
              <span className="font-medium">Agent settings…</span>
            </div>
          </button>
        ) : null}
      </div>
    </div>
  );
}

import { render, screen, fireEvent, cleanup } from "@testing-library/react";
import { describe, it, expect, vi, afterEach } from "vitest";
import { saveBrowserSettings } from "../lib/browserSettings";
import { NewTabPopover } from "./NewTabPopover";

afterEach(() => {
  cleanup();
  localStorage.clear();
});

describe("NewTabPopover", () => {
  it("renders an action-only menu without a search input", () => {
    render(
      <NewTabPopover
        open={true}
        onClose={vi.fn()}
        onNewTerminal={vi.fn()}
        onNewBrowser={vi.fn()}
      />
    );

    expect(screen.queryByRole("textbox")).not.toBeInTheDocument();
    expect(screen.getByText("New Terminal")).toBeInTheDocument();
    expect(screen.getByText("New Browser Tab")).toBeInTheDocument();
    expect(screen.queryByText("New Markdown")).not.toBeInTheDocument();
    expect(screen.queryByText("New Mobile Emulator")).not.toBeInTheDocument();
    expect(screen.queryByText("Agent settings…")).not.toBeInTheDocument();
  });

  it("renders optional actions when optional props are provided", () => {
    render(
      <NewTabPopover
        open={true}
        onClose={vi.fn()}
        onNewTerminal={vi.fn()}
        onNewBrowser={vi.fn()}
        onNewMarkdown={vi.fn()}
        onNewMobileEmulator={vi.fn()}
        onOpenSettings={vi.fn()}
      />
    );

    expect(screen.getByText("New Terminal")).toBeInTheDocument();
    expect(screen.getByText("New Browser Tab")).toBeInTheDocument();
    expect(screen.getByText("New Markdown")).toBeInTheDocument();
    expect(screen.getByText("New Mobile Emulator")).toBeInTheDocument();
    expect(screen.getByText("Agent settings…")).toBeInTheDocument();
  });

  it("calls onNewTerminal when New Terminal is clicked", () => {
    const onNewTerminal = vi.fn();
    const onClose = vi.fn();
    render(
      <NewTabPopover
        open={true}
        onClose={onClose}
        onNewTerminal={onNewTerminal}
        onNewBrowser={vi.fn()}
      />
    );

    fireEvent.click(screen.getByText("New Terminal"));
    expect(onNewTerminal).toHaveBeenCalled();
    expect(onClose).toHaveBeenCalled();
  });

  it("uses the configured new-tab URL when New Browser Tab is clicked", () => {
    saveBrowserSettings({ homePage: "https://example.com/start" });
    const onNewBrowser = vi.fn();
    const onClose = vi.fn();
    render(
      <NewTabPopover
        open={true}
        onClose={onClose}
        onNewTerminal={vi.fn()}
        onNewBrowser={onNewBrowser}
      />
    );

    fireEvent.click(screen.getByText("New Browser Tab"));

    expect(onNewBrowser).toHaveBeenCalledWith("https://example.com/start");
    expect(onClose).toHaveBeenCalled();
  });

  it("passes about:blank when New Browser Tab is clicked with no homepage", () => {
    const onNewBrowser = vi.fn();
    const onClose = vi.fn();
    render(
      <NewTabPopover
        open={true}
        onClose={onClose}
        onNewTerminal={vi.fn()}
        onNewBrowser={onNewBrowser}
      />
    );

    fireEvent.click(screen.getByText("New Browser Tab"));

    expect(onNewBrowser).toHaveBeenCalledWith("about:blank");
    expect(onClose).toHaveBeenCalled();
  });

  it("calls onNewMarkdown when New Markdown is clicked", () => {
    const onNewMarkdown = vi.fn();
    const onClose = vi.fn();
    render(
      <NewTabPopover
        open={true}
        onClose={onClose}
        onNewTerminal={vi.fn()}
        onNewBrowser={vi.fn()}
        onNewMarkdown={onNewMarkdown}
      />
    );

    fireEvent.click(screen.getByText("New Markdown"));
    expect(onNewMarkdown).toHaveBeenCalled();
    expect(onClose).toHaveBeenCalled();
  });

  it("calls onNewMobileEmulator when New Mobile Emulator is clicked", () => {
    const onNewMobileEmulator = vi.fn();
    const onClose = vi.fn();
    render(
      <NewTabPopover
        open={true}
        onClose={onClose}
        onNewTerminal={vi.fn()}
        onNewBrowser={vi.fn()}
        onNewMobileEmulator={onNewMobileEmulator}
      />
    );

    fireEvent.click(screen.getByText("New Mobile Emulator"));
    expect(onNewMobileEmulator).toHaveBeenCalled();
    expect(onClose).toHaveBeenCalled();
  });

  it("calls onOpenSettings when Agent settings… is clicked", () => {
    const onOpenSettings = vi.fn();
    const onClose = vi.fn();
    render(
      <NewTabPopover
        open={true}
        onClose={onClose}
        onNewTerminal={vi.fn()}
        onNewBrowser={vi.fn()}
        onOpenSettings={onOpenSettings}
      />
    );

    fireEvent.click(screen.getByText("Agent settings…"));
    expect(onOpenSettings).toHaveBeenCalled();
    expect(onClose).toHaveBeenCalled();
  });

  it("closes on Escape key", () => {
    const onClose = vi.fn();
    render(
      <NewTabPopover
        open={true}
        onClose={onClose}
        onNewTerminal={vi.fn()}
        onNewBrowser={vi.fn()}
      />
    );

    fireEvent.keyDown(window, { key: "Escape" });
    expect(onClose).toHaveBeenCalled();
  });

  it("renders agents group when agents prop is provided and triggers onLaunchAgent on click", () => {
    const onLaunchAgent = vi.fn();
    const onClose = vi.fn();
    const agents = [
      { name: "claude", command: "claude", args: "--model sonnet" },
      { name: "aider", command: "aider", args: "" },
    ];

    render(
      <NewTabPopover
        open={true}
        onClose={onClose}
        onNewTerminal={vi.fn()}
        onNewBrowser={vi.fn()}
        agents={agents}
        onLaunchAgent={onLaunchAgent}
      />
    );

    expect(screen.getByText("AGENTS")).toBeInTheDocument();
    expect(screen.getByText("Claude")).toBeInTheDocument();
    expect(screen.getByText("Aider")).toBeInTheDocument();

    fireEvent.click(screen.getByText("Claude"));
    expect(onLaunchAgent).toHaveBeenCalledWith(agents[0]);
    expect(onClose).toHaveBeenCalled();
  });
});

export const AGENT_CANDIDATES = [
  "claude",
  "codex",
  "gemini",
  "opencode",
  "aider",
  "cursor-agent",
  "droid",
  "crush",
] as const;

export type AgentCandidate = (typeof AGENT_CANDIDATES)[number];

export const AGENTS_SETTINGS_STORAGE_KEY = "ferryx.agents.v1";
export const AGENTS_SETTINGS_CHANGED_EVENT = "ferryx:agents-settings";

export type AgentOverride = {
  enabled?: boolean;
  command?: string;
  args?: string;
};

export type AgentSettings = {
  version: 1;
  defaultAgentId: string | null;
  overrides: Record<string, AgentOverride>;
};

export type ResolvedAgent = {
  name: string;
  available: boolean;
  enabled: boolean;
  command: string;
  args: string;
};

export const DEFAULT_AGENT_SETTINGS: AgentSettings = {
  version: 1,
  defaultAgentId: null,
  overrides: {},
};

function getStorage(storage?: Storage | null): Storage | null {
  if (storage !== undefined) return storage;
  if (typeof window !== "undefined" && window.localStorage) return window.localStorage;
  return null;
}

export function loadAgentSettings(storage?: Storage | null): AgentSettings {
  const store = getStorage(storage);
  if (!store) return { version: 1, defaultAgentId: null, overrides: {} };
  try {
    const raw = store.getItem(AGENTS_SETTINGS_STORAGE_KEY);
    if (!raw) return { version: 1, defaultAgentId: null, overrides: {} };
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object") return { version: 1, defaultAgentId: null, overrides: {} };

    const defaultAgentId = typeof parsed.defaultAgentId === "string" ? parsed.defaultAgentId : null;
    const rawOverrides = parsed.overrides && typeof parsed.overrides === "object" ? parsed.overrides : {};
    const overrides: Record<string, AgentOverride> = {};

    for (const [key, val] of Object.entries(rawOverrides)) {
      if (!val || typeof val !== "object") continue;
      const entry = val as Partial<AgentOverride>;
      overrides[key] = {
        enabled: typeof entry.enabled === "boolean" ? entry.enabled : undefined,
        command: typeof entry.command === "string" ? entry.command : undefined,
        args: typeof entry.args === "string" ? entry.args : undefined,
      };
    }

    return {
      version: 1,
      defaultAgentId,
      overrides,
    };
  } catch {
    return { version: 1, defaultAgentId: null, overrides: {} };
  }
}

export function saveAgentSettings(settings: AgentSettings, storage?: Storage | null): void {
  const store = getStorage(storage);
  if (!store) return;
  try {
    store.setItem(AGENTS_SETTINGS_STORAGE_KEY, JSON.stringify(settings));
    if (typeof window !== "undefined") {
      window.dispatchEvent(new CustomEvent(AGENTS_SETTINGS_CHANGED_EVENT, { detail: settings }));
    }
  } catch {
    // ignore storage quota / disabled storage
  }
}

export function mergeDetections(
  settings: AgentSettings,
  detections: Array<{ name: string; available: boolean }>,
): ResolvedAgent[] {
  const detectionMap = new Map<string, boolean>();
  if (Array.isArray(detections)) {
    for (const d of detections) {
      if (d && typeof d.name === "string") {
        detectionMap.set(d.name, Boolean(d.available));
      }
    }
  }

  return AGENT_CANDIDATES.map((name) => {
    const available = detectionMap.get(name) ?? false;
    const override = settings?.overrides?.[name];
    const enabled = override?.enabled !== undefined ? override.enabled : available;
    const command = override?.command !== undefined && override.command.trim() !== "" ? override.command : name;
    const args = override?.args ?? "";

    return {
      name,
      available,
      enabled,
      command,
      args,
    };
  });
}

